-- Loopback PostgreSQL only; all large synthetic history rolls back.
begin;
set local statement_timeout='30s';
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('e6700000-0000-4000-8000-000000000001','e2e-quality-coach@example.test'),('e6700000-0000-4000-8000-000000000002','e2e-quality-guardian@example.test');
insert into public.studios(id,name,slug) values('e6700000-0000-4000-8000-000000000003','Quality large fixture','e2e-quality-large');
insert into public.memberships(studio_id,user_id,role,display_name) values('e6700000-0000-4000-8000-000000000003','e6700000-0000-4000-8000-000000000001','coach','Fixture');
insert into public.students(id,studio_id,full_name,portal_enabled) select md5('e2e-quality-student-'||n)::uuid,'e6700000-0000-4000-8000-000000000003','Scale Learner '||n,true from generate_series(1,1000)n;
insert into public.lessons(studio_id,student_id,topic,starts_at,ends_at,status,location_type,location_label) select 'e6700000-0000-4000-8000-000000000003',md5('e2e-quality-student-'||(1+n%1000))::uuid,'Scale lesson '||n,'2020-01-01'::timestamptz+n*interval '1 hour','2020-01-01'::timestamptz+n*interval '1 hour'+interval '45 minutes','completed','in_person','Synthetic studio' from generate_series(1,10000)n;
insert into public.materials(studio_id,title,in_library,text_content,media_kind) select 'e6700000-0000-4000-8000-000000000003','Scale resource '||n,true,'Synthetic reading content','document' from generate_series(1,1000)n;
insert into public.packages(student_id,name) select md5('e2e-quality-student-1')::uuid,'Scale package '||n from generate_series(1,20)n;
insert into public.assignments(student_id,title) select md5('e2e-quality-student-1')::uuid,'Legacy work '||n from generate_series(1,200)n;
insert into public.material_links(material_id,student_id,role,visible_to_student) select m.id,md5('e2e-quality-student-1')::uuid,'library',true from public.materials m where m.studio_id='e6700000-0000-4000-8000-000000000003';
insert into public.linked_contacts(studio_id,student_id,user_id,full_name,email,portal_enabled,can_view_work,can_view_schedule) select 'e6700000-0000-4000-8000-000000000003',md5('e2e-quality-student-'||n)::uuid,'e6700000-0000-4000-8000-000000000002','Synthetic guardian','e2e-quality-guardian@example.test',true,true,true from generate_series(1,2)n;
insert into public.conversations(id,studio_id,kind,title,student_id) values('e6700000-0000-4000-8000-000000000004','e6700000-0000-4000-8000-000000000003','direct','Scale communication',md5('e2e-quality-student-1')::uuid);
insert into public.conversation_messages(conversation_id,studio_id,author_role,author_name,body) select 'e6700000-0000-4000-8000-000000000004','e6700000-0000-4000-8000-000000000003','coach','Synthetic coach','Scale message '||n from generate_series(1,4000)n;
set local role authenticated;
select set_config('request.jwt.claim.sub','e6700000-0000-4000-8000-000000000001',true);
select ok(jsonb_array_length(public.studio_global_search('Scale')->'items')<=25,'Search stays bounded with 1000 students, 10000 lessons and 1000 resources');
select ok(jsonb_array_length(public.studio_global_search('Scale',null,'lesson',2)->'items')<=20,'Expanded lesson search page stays bounded');
select ok(jsonb_array_length(public.search_material_resources('e6700000-0000-4000-8000-000000000003')->'items')<=25,'Library retrieval stays bounded');
select ok(jsonb_array_length(public.search_material_resources('e6700000-0000-4000-8000-000000000003',null,true,'','{}','active',false,'title',2)->'items')<=25,'Library second page stays bounded');
select ok(jsonb_array_length(public.communication_activity(1)->'items')<=25,'Activity retrieval stays bounded with 4000 messages');
select ok(jsonb_array_length(public.communication_activity(2)->'items')<=25,'Activity second page stays bounded');
select lives_ok(format($$select public.student_workspace_summary(%L)$$,md5('e2e-quality-student-1')::uuid),'Summary handles mixed legacy/canonical work and multiple packages');
select set_config('request.jwt.claim.sub','e6700000-0000-4000-8000-000000000002',true);
select is(jsonb_array_length(public.portal_student_contexts()->'items'),2,'Guardian sees exactly two authorized students among 1000');
select is(public.portal_student_contexts(md5('e2e-quality-student-3')::uuid)->'selected','null'::jsonb,'Forged student selection returns no preview');
select ok(jsonb_array_length(public.studio_global_search('Scale',md5('e2e-quality-student-1')::uuid)->'items')<=25,'Guardian search remains bounded and scoped');
select * from finish();
rollback;
